const n: integer = 1;
const s: string = "hi";
const a: integer[] = [1, 2];
const b: Array<string> = ["x"];
const t: [integer, string] = [1, "a"];
const u: integer | string = 1;
const o: { host: string, port?: integer } = { host: "h" };
const f: (a: integer) => integer = function (a: integer): integer {
    return a + 1;
};

type Id = integer;
interface Base {
    id: integer
};
interface Person extends Base {
    name: string,
    age?: integer
};
const p: Person = { id: 1, name: "ada" };

#typecheck;                          // full on
#typecheck on;
#typecheck compileOnly;
#typecheck off;
#typecheck on noImplicitAny;
#typecheck on noImplicitAny strictNullChecks;
#typecheck strict;                     // full + noImplicitAny + strictNullChecks
#typecheck on, noImplicitAny;          // commas optional

#typecheck;

const ok: integer = 1;
// const bad: integer = "no";   // type error

const nums: integer[] = [1, 2, 3];
// const mixed: integer[] = [1, "x"];  // type error when elements are checked

interface Point {
    x: integer,
    y: integer
};
const p: Point = { x: 0, y: 0 };
// const q: Point = { x: 0 };   // missing required y
